"""Promote the Gelfand band-value route from Work to Checked by script (run 2026-11-18T1028Z; after
runs/2026-11-18T0428Z/scripts/promote_gelfand_count.py). Copies Work/Math/{GLamCell,GLamData,GLamChain,GLamBands,
GelfandPDECountValuesMain,GelfandPDECountValues}.lean to Checked/Math/, renames the Work namespaces, drops
`import Mathlib` from the headline module, replaces each module doc by one without numerals (check_prose rule 7)."""
import re
mods = ['GLamCell', 'GLamData', 'GLamChain', 'GLamBands', 'GelfandPDECountValuesMain', 'GelfandPDECountValues']
docs = {
 'GLamCell': 'Gelfand problem, `GLamCell`: chains of the validated homology cells of `Checked.Math.BEHCell` with new invariants for the turning points of the branch parameter λ = u v: the sign of v − two (λ decreases where v exceeds two, increases where v is below two), the sign of u − one (v increases where u exceeds one, decreases where u is below one), and a band for u on every cell of the chain. The cell check `CellProp`, the links and the end condition are those of `Checked.Math.BEHCell`; only the invariant is new. Promoted from `Work/Math/GLamCell.lean` (run 2026-11-18T1028Z).',
 'GLamData': 'Gelfand problem, `GLamData`: validated homology cells of the regular isothermal solution from the first turning point of the branch parameter to beyond the third, as data (generator `runs/2026-11-18T1028Z/scripts/gen_gl.py`, emitter `emit_gl.py`), each segment decided by kernel evaluation with its invariant of `GLamCell`. Promoted from `Work/Math/GLamData.lean` (run 2026-11-18T1028Z).',
 'GLamChain': 'Gelfand problem, `GLamChain`: the cells of `GLamData` chained along every solution of the homology system that starts in the first cell\'s input box (generated by `runs/2026-11-18T1028Z/scripts/emit_gl.py`). Promoted from `Work/Math/GLamChain.lean` (run 2026-11-18T1028Z).',
 'GLamBands': 'Gelfand problem, `GLamBands`: the values of the branch parameter λ(s) = s² e^{w(s)} of the regular isothermal solution at its second and third turning points, for every sequence of turning points with the monotonicity pattern of `Checked.Math.GelfandExtrema.gelfand_extrema`. Route: the start enclosure of `Checked.Math.GCerts.chain` at the first turning point, the certified homology cells of `GLamChain` beyond it (λ decreases where v exceeds two and increases where v is below two; v is strictly monotone on the two bracket intervals), the zeros of v − two found by the intermediate value theorem, identified with the given turning points by comparing strict monotonicity of λ at two points, and λ = two times u at a zero of v − two. Promoted from `Work/Math/GLamBands.lean` (run 2026-11-18T1028Z).',
 'GelfandPDECountValuesMain': 'Gelfand problem in the three-dimensional ball as a PDE, `GelfandPDECountValuesMain`: the proof route of `Checked.Math.GelfandPDECountValues.gelfand_pde_radial_count_values`. The count proof of `Checked.Math.GelfandPDECountMain.main` (copied; `reduce`, `profile` reused), with the band ends, the values of the branch parameter at its second and third turning points, enclosed by `Checked.Math.GLamBands.bands` in place of the bounds against two. Promoted from `Work/Math/GelfandPDECountValuesMain.lean` (run 2026-11-18T1028Z).',
 'GelfandPDECountValues': 'Gelfand problem in the three-dimensional ball as a PDE, `GelfandPDECountValues`: the exact counts of radial classical solutions of `Checked.Math.GelfandPDECount.gelfand_pde_radial_count`, count clauses unchanged, with the two band ends (the first minimum and the second maximum of the branch parameter) enclosed by numbers. Promoted from `Work/Math/GelfandPDECountValues.lean` (frozen, proved and audited by run 2026-11-18T1028Z); the route is `GelfandPDECountValuesMain`.',
}
for m in mods:
    s = open('Work/Math/%s.lean' % m).read()
    for n in mods:
        s = s.replace('Work.Math.%s' % n, 'Checked.Math.%s' % n)
    s = s.replace('import Mathlib\n', '', 1) if m == 'GelfandPDECountValues' else s
    s, k = re.subn(r'/-!.*?-/', lambda _: '/-! ' + docs[m] + ' -/', s, count=1, flags=re.S)
    assert k == 1
    s = s.rstrip('\n') + '\n'
    assert 'Work.' not in s, m
    assert 'import Mathlib\n' not in s, m
    open('Checked/Math/%s.lean' % m, 'w').write(s)
print('ok')
